?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Owner Control — Lab Store Offers</title><style>:root{color-scheme:dark;font-family:system-ui,sans-serif}body{margin:0;background:#111820;color:#f4f7fb;padding:24px}main{max-width:1050px;margin:auto}a{color:#f6cc65}.lede,.meta{color:#b8c6d2}.cards{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin-top:20px}.card{background:#1b2530;border:1px solid #33404c;border-radius:12px;overflow:hidden}.card-copy{padding:16px}.card h2{margin:0 0 8px;font-size:1.1rem}.card p{margin:0;color:#b8c6d2;line-height:1.5}.offer-media{display:block;width:100%;height:180px;object-fit:contain;background:#0d141c}.media-fallback{display:grid;place-items:center;width:100%;height:180px;margin:0;background:#0d141c;color:#b8c6d2;font-size:.9rem}#status{min-height:1.5em;padding:12px;border-left:3px solid #f6cc65;background:#18232e}@media(max-width:560px){body{padding:16px}.cards{grid-template-columns:1fr}}</style></head><body><main><p><a href="/owner-control/v1/index.php">← Owner Control</a></p><h1>Lab Store Offers</h1><p class="lede">Owner-only, read-only offer presentation. No protected action controls are available.</p><p id="status" role="status">Loading offer presentation…</p><section id="cards" class="cards" aria-label="Lab Store offer presentation"></section></main><script>'use strict';const fields=['source_type','category','title','offer_active','source_available','presentation_ref','media_kind'],status=document.getElementById('status'),cards=document.getElementById('cards');function valid(o){return o&&typeof o==='object'&&Object.keys(o).every(k=>fields.includes(k))&&(o.source_type==='normal_store'||o.source_type==='genetic_item')&&typeof o.category==='string'&&typeof o.title==='string'&&typeof o.offer_active==='boolean'&&typeof o.source_available==='boolean'&&(typeof o.presentation_ref==='string'||o.presentation_ref===null)&&(o.media_kind==='image'||o.media_kind==='media_unavailable')}function mediaUnavailable(){const fallback=document.createElement('p');fallback.className='media-fallback';fallback.textContent='Media unavailable';return fallback}async function load(){try{const response=await fetch('/api/owner-control/v1/lab-store/offers.php',{credentials:'same-origin',cache:'no-store'}),payload=await response.json();if(!response.ok||!payload||payload.success!==true||payload.capability!=='owner_control_lab_store_offers_read'||payload.mode!=='read_only'||payload.writes!==false||!Array.isArray(payload.offers)||!payload.offers.every(valid))throw Error();const fragment=document.createDocumentFragment();for(const offer of payload.offers){const card=document.createElement('article');card.className='card';if(offer.presentation_ref!==null){const image=document.createElement('img');image.className='offer-media';image.alt='';image.addEventListener('error',()=>image.replaceWith(mediaUnavailable()),{once:true});image.src=offer.presentation_ref;card.append(image)}else{card.append(mediaUnavailable())}const copy=document.createElement('div'),title=document.createElement('h2'),detail=document.createElement('p');copy.className='card-copy';title.textContent=offer.title;detail.textContent=offer.category+' · '+(offer.offer_active?'Active':'Inactive')+' · '+(offer.source_available?'Available':'Unavailable');copy.append(title,detail);card.append(copy);fragment.append(card)}cards.replaceChildren(fragment);status.textContent=payload.offers.length?'Read-only offer presentation loaded.':'No Lab Store offer presentation is available.'}catch(error){cards.replaceChildren();status.textContent='Lab Store offer presentation is currently unavailable.'}}load();</script></body></html>
